import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------------
# CUDA source implementing row‑wise softmax for FP16 tensors (A100, CC 8.0)
# ------------------------------------------------------------------------
cuda_src = r'''
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <torch/types.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/ATen.h>
#include <cmath>

#define BLOCK_SIZE 256   // must be power‑of‑two and <= 1024

extern "C"
__global__ void softmax_fp16_kernel(const half* __restrict__ input,
                                    half* __restrict__ output,
                                    int rows, int cols) {
    int row = blockIdx.x;
    if (row >= rows) return;

    // ---------- max reduction ----------
    float max_val = -FLT_MAX;
    for (int c = threadIdx.x; c < cols; c += BLOCK_SIZE) {
        float v = __half2float(input[row * cols + c]);
        max_val = fmaxf(max_val, v);
    }
    __shared__ float smax[BLOCK_SIZE];
    smax[threadIdx.x] = max_val;
    __syncthreads();
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smax[threadIdx.x] = fmaxf(smax[threadIdx.x], smax[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    max_val = smax[0];
    __syncthreads();

    // ---------- sum of exp ----------
    float sum = 0.0f;
    for (int c = threadIdx.x; c < cols; c += BLOCK_SIZE) {
        float v = __half2float(input[row * cols + c]);
        sum += expf(v - max_val);
    }
    __shared__ float ssum[BLOCK_SIZE];
    ssum[threadIdx.x] = sum;
    __syncthreads();
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            ssum[threadIdx.x] += ssum[threadIdx.x + stride];
        }
        __syncthreads();
    }
    sum = ssum[0];
    __syncthreads();

    // ---------- write softmax ----------
    for (int c = threadIdx.x; c < cols; c += BLOCK_SIZE) {
        float v = __half2float(input[row * cols + c]);
        float soft = expf(v - max_val) / sum;
        output[row * cols + c] = __float2half(soft);
    }
}
'''

# Compile the inline extension
softmax_ext = load_inline(name='softmax_fp16_ext',
                          cpp_sources='',
                          cuda_sources=cuda_src,
                          functions=['softmax_fp16_kernel'],
                          verbose=False)

# ------------------------------------------------------------------------
# PyTorch module that uses the custom kernel
# ------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Model that applies a row‑wise Softmax using a custom CUDA kernel.
    All tensors are FP16.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects CUDA tensors")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects float16 tensors")
        if x.dim() != 2:
            raise RuntimeError("ModelNew expects a 2‑D tensor (batch, features)")

        batch, dim = x.shape
        out = torch.empty_like(x)

        # Launch configuration: one block per row
        threads = 256  # BLOCK_SIZE
        blocks = batch

        stream = torch.cuda.current_stream().cuda_stream
        softmax_ext.softmax_fp16_kernel(
            grid=(blocks,),
            block=(threads,),
            args=[x.data_ptr(), out.data_ptr(), batch, dim],
            stream=stream
        )
        return out

# ------------------------------------------------------------------------
# Helper functions mirroring the reference script
# ------------------------------------------------------------------------
def get_inputs():
    # match reference: default dtype is float32, convert to FP16 & CUDA
    x = torch.rand(4096, 393216, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return []   # No special init inputs needed
